// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address newImplementation) public {
        // The property: proxiableUUID must return the expected ERC1967 implementation slot constant
        // (0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc)
        // and may not revert.
        // Since the contract is not behind a proxy and not initialized, calling proxiableUUID
        // directly on the implementation reverts with UUPSUnauthorizedCallContext.
        // The test verifies the revert behavior. In the reference, it always reverts;
        // the bug does not change that. However, to trigger the difference, the test must go
        // through a proxy so that the `notDelegated` modifier passes and the actual return
        // value becomes observable.
        // However, a fuzzed address parameter cannot be a valid proxy with code.
        // We therefore deploy a minimal adversarial proxy helper that delegates to `c`.
        // The proxy's `proxiableUUID()` will return what `c.proxiableUUID()` returns.
        Proxy proxy = new Proxy(address(c));
        bool ok;
        bytes memory ret;
        try proxy.proxiableUUID() returns (bytes32 uuid) {
            ok = true;
            ret = abi.encode(uuid);
        } catch {
            ok = false;
        }
        // The reference must not revert and must return the correct implementation slot.
        // The mutant either reverts or returns a different value.
        bytes32 expectedSlot = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;
        assertTrue(ok && abi.decode(ret, (bytes32)) == expectedSlot);
    }
}

contract Proxy {
    address private immutable _implementation;
    constructor(address impl) payable {
        _implementation = impl;
    }

    fallback(bytes calldata data) external payable returns (bytes memory) {
        (bool ok, bytes memory ret) = _implementation.delegatecall(data);
        if (!ok) {
            assembly { revert(add(ret,0x20), mload(ret)) }
        }
        return ret;
    }
}

