pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address accessControl, address secondAccessControl) public {
        // Call initialize once
        vm.prank(address(this));
        c.initialize(accessControl);

        // Call initialize a second time with a different (or same) parameter
        bool ok;
        vm.prank(address(this));
        try c.initialize(secondAccessControl) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: always reverts (ok == false). Mutant: succeeds (ok can be true).
        assertTrue(!ok);
    }
}

