pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address initialAdmin, address maliciousAdmin) public {
        vm.assume(caller != address(0));
        vm.assume(initialAdmin != address(0));
        vm.assume(maliciousAdmin != address(0));
        vm.assume(initialAdmin != maliciousAdmin);

        vm.prank(caller);
        c.initialize(initialAdmin);

        // Get the access control storage after first initialization
        (bool okFirst, bytes memory dataFirst) = address(c).call(abi.encodeWithSignature("getAccessStorage()"));
        // Access storage is internal, we check via the cast to IAccessControl
        address accessControlAfterFirst = address(uint160(uint256(bytes32(dataFirst))));

        // Try second initialization with a different malicious admin
        bool secondInitSucceeded;
        vm.prank(caller);
        try c.initialize(maliciousAdmin) {
            secondInitSucceeded = true;
        } catch {
            secondInitSucceeded = false;
        }

        // Try to check access control after potential reinit
        (bool okSecond, bytes memory dataSecond) = address(c).call(abi.encodeWithSignature("getAccessStorage()"));
        address accessControlAfterSecond = address(uint160(uint256(bytes32(dataSecond))));

        // Rule: the second initialization MUST fail (reference reverts, mutant doesn't).
        // If it fails, access control MUST remain the initial admin;
        // If it succeeds (which is the bug), access control would change.
        assertTrue(!secondInitSucceeded || accessControlAfterSecond == initialAdmin);
    }
}

