pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address accessControl1, address accessControl2) public {
        // 1. Ensure the two fuzzed access control addresses are distinct and non-zero
        vm.assume(accessControl1 != address(0));
        vm.assume(accessControl2 != address(0));
        vm.assume(accessControl1 != accessControl2);

        // 2. Initialize with first access control
        c.initialize(accessControl1);
        // Call initialize again with a different access control; the reference reverts, the mutant succeeds
        try c.initialize(accessControl2) returns (bool) {
            // Mutant case: second initialize succeeded, access control could be overwritten.
            // If it succeeded, the stored access control must still equal the first one, otherwise the mutant broke the invariant.
            assertEq(c.getAccessStorage().accessControl, accessControl1);
        } catch {
            // Reference case: second initialize reverted, access control remains unchanged.
            // This is a safe outcome; assertion always passes here.
            assertTrue(true);
        }
    }
}

