pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address accessControl) public {
        vm.assume(accessControl != address(0));
        // First initialization should succeed
        c.initialize(accessControl);
        // Second initialization attempt should revert in both contracts,
        // but the internal state differs. We test that the contract is still initializing.
        // In reference, after first call _initializing is false, so a second call
        // will fail with InvalidInitialization because _initialized == 1 and address(this).code.length > 0.
        // In mutant, _disableInitializers sets _initialized to type(uint64).max and reverts
        // the second call with InvalidInitialization as well.
        // The observable difference is via _getInitializedVersion() which is internal.
        // We need an external interaction. We use upgradeToAndCall which requires authorization
        // and check that the upgrade path is available only when properly initialized.
        // Properly initialized contract (reference) has UUPS working, while mutant is broken.
        // The _authorizeUpgrade checks access, so we need a valid access control.
        // We deploy a mock access control that grants access.
        MockAccessControl mock = new MockAccessControl();
        c = new C();
        c.initialize(address(mock));
        mock.setAccess(true);
        // Now upgrade should succeed in reference, but mutant has _disableInitializers called,
        // which doesn't affect proxiableUUID but might affect storage. Actually _disableInitializers
        // only sets _initialized, doesn't break UUPS directly.
        // The bug changes __UUPSUpgradeable_init() to _disableInitializers().
        // __UUPSUpgradeable_init() is a no-op in reference, so the difference is only
        // the call to _disableInitializers() which locks initialization.
        // The rule: after initialize, the contract should be in an 'initialized' state (version 1),
        // not 'disabled' state (version max). This is observable through reinitializer modifier.
        // Reinitializer requires version > current, but if current is max, it fails.
        // C has no reinitializer, but we can check via a newly deployed contract that uses
        // the same Initializable storage slot. Not possible.
        // Alternatively, check that the contract is not in initializing state via a call that
        // uses onlyInitializing modifier. C has no such external function.
        // Therefore, the difference is only in the internal storage. The only external effect
        // is if any function uses _isInitializing() or _getInitializedVersion() externally.
        // None do. Thus, the bug is not externally observable except via a second initialize call
        // which both revert. The property "initialize can be called exactly once" holds for both.
        // Wait, the prompt says "Driven through the public/external entry `initialize`, P and M differ in this way:
        // after a call to `initialize(...)` completes, the value of state variable `initialize` differs: `P.initialize() != M.initialize()`."
        // This suggests the function selector `initialize` is somehow different. But `initialize` is a function, not a state variable.
        // Perhaps they mean the internal state after initialization. The only external difference is that
        // after initialization, calling upgradeToAndCall might behave differently because
        // _authorizeUpgrade uses checkAccess, and Access initialization sets accessControl.
        // In reference, Access is initialized (accessControl set). In mutant, Access is also initialized before _disableInitializers.
        // So both have accessControl set. The UUPS upgrade is functional in both.
        // Let's re-read the mutant: "Replace __UUPSUpgradeable_init() with _disableInitializers()".
        // In reference, initialize calls __Access_init, __UUPSUpgradeable_init.
        // __UUPSUpgradeable_init is onlyInitializing and does nothing.
        // _disableInitializers sets _initialized to type(uint64).max if not initializing.
        // But inside initializer, _initializing is true, so _disableInitializers will revert with InvalidInitialization! (see _disableInitializers: if ($._initializing) revert)
        // So the mutant's initialize will revert when it calls _disableInitializers!
        // Because inside initializer, _initializing is true.
        // Therefore, reference initialize succeeds, mutant initialize reverts.
        // That is the observable difference!
        // So the property: initialize should succeed (not revert) when called with valid parameters.
        // We'll test exactly one assertion: that initialize does not revert.
        bool ok;
        try c.initialize(accessControl) { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

contract MockAccessControl {
    bool grant;
    function setAccess(bool g) external { grant = g; }
    function checkAccess(bytes4, address, address) external view returns (bool) { return grant; }
}

