pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address accessControl, address newImplementation) public {
        vm.assume(accessControl != address(0));
        vm.assume(newImplementation != address(0));
        // Deploy a mock access control that always returns true for checkAccess
        MockAccessControl mac = new MockAccessControl();
        // Deploy a valid new implementation (any contract with code)
        bytes memory newImplCode = type(MockImplementation).creationCode;
        address impl = address(new MockImplementation());
        // Initialize C with the mock access control
        c.initialize(address(mac));
        // Attempt upgradeToAndCall as the proxy (which is not the case here, but we call directly on c)
        // The bug: _disableInitializers sets _initialized to type(uint64).max, which alters _checkProxy behavior.
        // In the reference, the __self check prevents direct calls from succeeding.
        // In the buggy version, the initialization state is corrupted, making the __self check not revert when it should.
        // We call upgradeToAndCall directly on c (not behind a proxy); reference should revert, buggy might succeed.
        bool success = true;
        try c.upgradeToAndCall(impl, "") {
            success = true;
        } catch {
            success = false;
        }
        // Reference: direct call to upgradeToAndCall should always revert (UUPSUnauthorizedCallContext).
        // Buggy: may succeed because _disableInitializers corrupts the initialization state, bypassing __self check.
        assertTrue(!success);
    }
}

contract MockAccessControl {
    function checkAccess(bytes4, address, address) external pure returns (bool) {
        return true;
    }
    function initialize(address) external {}
}

contract MockImplementation {
    function proxiableUUID() external pure returns (bytes32) {
        return 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;
    }
}

