pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address accessControl) public {
        vm.assume(accessControl != address(0));
        // First, a proper top-level initialize via external call
        c.initialize(accessControl);
        // Now attempt a second initialize via delegatecall from a minimal proxy,
        // which should revert in the reference version but not in the buggy one.
        CallerProxy proxy = new CallerProxy();
        try proxy.delegateInit(address(c), accessControl) returns (bool ok) {
            // If we get here, the second initialize succeeded.
            // On the reference contract, this should be unreachable.
            assertTrue(false);
        } catch {
            // Reference: second initialize reverts -> expected behavior
            assertTrue(true);
        }
    }
}

contract CallerProxy {
    function delegateInit(address target, address accessControl) external returns (bool) {
        (bool success, ) = target.delegatecall(abi.encodeWithSignature("initialize(address)", accessControl));
        return success;
    }
}

