pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C public c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address accessControl) public {
        vm.assume(accessControl != address(0));

        MiddleProxy proxy = new MiddleProxy(address(c));
        bytes memory initData = abi.encodeCall(C.initialize, (accessControl));

        (bool proxyOk,) = address(proxy).call(abi.encodeCall(MiddleProxy.proxyExec, (initData)));
        require(proxyOk, "proxy call failed");

        bool directOk;
        try c.initialize(accessControl) {
            directOk = true;
        } catch {
            directOk = false;
        }

        assertTrue(!directOk);
    }
}

contract MiddleProxy {
    address public immutable target;

    constructor(address _target) {
        target = _target;
    }

    function proxyExec(bytes memory initData) external {
        (bool success,) = target.delegatecall(abi.encodeWithSignature("initialize(address)", abi.decode(initData, (address))));
        require(success, "delegatecall failed");
    }
}

