pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address accessControl, uint64 initialVersion) public {
        vm.assume(accessControl != address(0));
        vm.assume(initialVersion < type(uint64).max);
        // 1. Perform a direct top-level initialization
        vm.prank(address(0xdead));
        c.initialize(accessControl);

        // 2. Deploy a helper that delegatecalls back to initialize on C, simulating a non-top-level call
        ReinitializerHelper helper = new ReinitializerHelper();

        // 3. Execute the non-top-level initialization via delegatecall; record success
        bool nestedSuccess;
        try helper.trigger(address(c), abi.encodeWithSelector(C.initialize.selector, accessControl)) {
            nestedSuccess = true;
        } catch {
            nestedSuccess = false;
        }

        // 4. Read the current initialized version from C
        uint64 currentVersion = c._getInitializedVersion();

        // The rule: After a direct initialization, the version must stay at 1 if a nested (non-top-level)
        // re-initialization succeeds (the reference rejects it; the bug allows it, producing version > 1).
        assertTrue(!nestedSuccess || currentVersion == 1);
    }
}

contract ReinitializerHelper {
    function trigger(address target, bytes memory data) external returns (bool) {
        (bool success, ) = target.delegatecall(data);
        return success;
    }
}

