pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address accessControl) public {
        vm.assume(accessControl != address(0));
        // The reference C emits Initialized(1) after a valid initialize call,
        // so we check that the returned version matches the emitted version by
        // analyzing the emitted events and comparing with a direct callable
        // version getter. Since _getInitializedVersion is internal, we rely on
        // the fact that trying to re-initialize with version 2 will fail on the
