        c.setSlopes(asset, slopes);
        c.setLimits(maxMultiplier, minMultiplier, rateLimit);

        // Set up the utilization data storage directly via the storage util to simulate a previous state
        // We access the storage slot computed by VaultAdapterStorageUtils
        bytes32 slot = 0x2b1d5d801322d1007f654ac87d8072a5f5ca4203517edc869ef2aa54addad600;
        bytes32 utilizationDataSlot = keccak256(abi.encode(keccak256(abi.encode(vault, asset)), uint256(slot) + 1));
        // utilizationData is a mapping(address => mapping(address => UtilizationData))
        // Slot of utilizationData[vault][asset] is keccak256(asset . keccak256(vault . slotBase)), where slotBase = 1 (mapping of address => UtilizationData) + slot?
        // Actual struct layout: struct VaultAdapterStorage {
        //     mapping(address => SlopeData) slopeData;  // slot 0
        //     mapping(address => mapping(address => UtilizationData)) utilizationData; // slot 1
        //     uint256 maxMultiplier; // slot 2
        //     uint256 minMultiplier; // slot 3
        //     uint256 rate; // slot 4
        // }
        // Storage slot for utilizationData[vault][asset] is keccak256(asset . keccak256(vault . 1))
        bytes32 vaultMappingSlot = keccak256(abi.encode(vault, 1));
        bytes32 dataSlot = keccak256(abi.encode(asset, vaultMappingSlot));
        // UtilizationData struct: multiplier (slot), index (slot+1), lastUpdate (slot+2)
        vm.store(address(c), dataSlot, bytes32(uint256(1e27))); // multiplier = 1e27
        vm.store(address(c), bytes32(uint256(dataSlot) + 1), bytes32(lastUtilizationIndex));
        vm.store(address(c), bytes32(uint256(dataSlot) + 2), bytes32(lastUpdate));

