        uint256 expectedRate = computeReferenceRate(lastUpdate, currentTimestamp, lastUtilizationIndex, currentUtilizationIndex, maxMultiplier, minMultiplier, rateLimit, kink, slope0, slope1);
        assertTrue(returnedRate == expectedRate);
    }

    function computeReferenceRate(uint256 lastUpdate, uint256 currentTimestamp, uint256 lastIndex, uint256 currentIndex, uint256 maxMultiplier, uint256 minMultiplier, uint256 rateLimit, uint256 kink, uint256 slope0, uint256 slope1) private pure returns (uint256) {
        uint256 elapsed = currentTimestamp - lastUpdate;
        uint256 utilization;
        if (elapsed != currentTimestamp) {
            utilization = (currentIndex - lastIndex) / elapsed;
        } else {
            // This case won't happen in the test because we assume lastUpdate > 0 and currentTimestamp != elapsed
            utilization = 0;
        }

        uint256 multiplier = 1e27;
        uint256 interestRate;
        if (utilization > kink) {
            uint256 excess = utilization - kink;
            multiplier = multiplier * (1e27 + (1e27 * excess / (1e27 - kink)) * elapsed * rateLimit / 1e27) / 1e27;
            if (multiplier > maxMultiplier) {
                multiplier = maxMultiplier;
            }
            interestRate = (slope0 + (slope1 * excess / 1e27)) * multiplier / 1e27;
