            multiplier = multiplier * 1e27 / (1e27 + (1e27 * (kink - utilization) / kink) * elapsed * rateLimit / 1e27);
            if (multiplier < minMultiplier) {
                multiplier = minMultiplier;
            }
            interestRate = (slope0 * utilization / kink) * multiplier / 1e27;
        }
        return interestRate;
    }
}

